gboolean pango_emoji_iter_next_emoji(PangoEmojiIter *iter) {
  if (iter->index >= iter->text_len)
    return FALSE;

  iter->start = iter->index;
  gunichar c = g_utf8_get_char(iter->text + iter->start);
  iter->index += g_utf8_next_char(iter->text + iter->start) - (iter->text + iter->start);

  if (PANGO_IS_EMOJI(c)) {
    iter->is_emoji = TRUE;
    return TRUE;
  }

  while (iter->index < iter->text_len) {
    gunichar next_c = g_utf8_get_char(iter->text + iter->index);
    if (next_c == 0x200D) { /* Zero-width joiner */
      iter->index += g_utf8_next_char(iter->text + iter->index) - (iter->text + iter->index);
      c = next_c;
      continue;
    } else if (next_c == 0xFE0F || next_c == 0xFE0E) { /* Variation selector */
      iter->index += g_utf8_next_char(iter->text + iter->index) - (iter->text + iter->index);
      c = next_c;
      continue;
    } else if (PANGO_IS_EMOJI(next_c)) {
      iter->start = iter->index;
      iter->index += g_utf8_next_char(iter->text + iter->start) - (iter->text + iter->start);
      iter->is_emoji = TRUE;
      return TRUE;
    } else {
      break;
    }
  }

  iter->is_emoji = FALSE;
  return FALSE;
}

gboolean pango_emoji_iter_next (PangoEmojiIter *iter) {
  const gchar *text;
  gint len;
  gchar *start;
  gchar *end;
  gchar *current;

  text = iter->text;
  len = iter->text_len;

  if (iter->pos >= len)
    return FALSE;

  start = (gchar *)text + iter->pos;
  end = (gchar *)text + len;
  current = start;

  while (current < end) {
    gunichar ch = g_utf8_get_char (current);
    gint char_len = g_utf8_next_char (current) - current;

    if (g_unichar_isspace (ch) || g_unichar_ismbc (ch) || g_unichar_isalnum (ch)) {
      current += char_len;
      continue;
    }

    if (g_unichar_emoji (ch)) {
      iter->is_emoji = TRUE;
      iter->start = current - start;
      iter->end = iter->start + char_len;
      iter->pos += char_len;
      return TRUE;
    }

    if (ch == 0x200D || ch == 0xFE0F || ch == 0xFE0E) {
      current += char_len;
      continue;
    }

    if (g_unichar_iszerowidthjoiner (ch)) {
      current += char_len;
      continue;
    }

    current += char_len;
  }

  iter->is_emoji = FALSE;
  iter->pos = len;
  return FALSE;
}

gboolean pango_emoji_iter_next_emoji(PangoEmojiIter *iter) {
  if (iter->pos >= iter->text_len)
    return FALSE;

  gboolean found_emoji = FALSE;
  gunichar c = iter->text[iter->pos];

  if (pango_is_emoji(c)) {
    iter->emoji_start = iter->pos;
    iter->emoji_end = iter->pos + 1;
    iter->is_emoji = TRUE;
    found_emoji = TRUE;
    iter->pos += 1;
  } else {
    iter->is_emoji = FALSE;
    iter->pos += 1;
  }

  while (iter->pos < iter->text_len && !found_emoji) {
    gunichar next_c = iter->text[iter->pos];
    if (PANGO_UNICODE_IS_JOINER(next_c) || PANGO_UNICODE_IS_VARIATION_SELECTOR(next_c)) {
      if (iter->is_emoji) {
        iter->emoji_end = iter->pos;
        found_emoji = TRUE;
      }
      iter->pos += 1;
    } else {
      break;
    }
  }

  if (!found_emoji && iter->pos < iter->text_len) {
    gunichar next_c = iter->text[iter->pos];
    if (pango_is_emoji(next_c)) {
      iter->emoji_start = iter->pos;
      iter->emoji_end = iter->pos + 1;
      iter->is_emoji = TRUE;
      found_emoji = TRUE;
      iter->pos += 1;
    } else {
      iter->is_emoji = FALSE;
      iter->pos += 1;
    }
  }

  if (iter->pos >= iter->text_len)
    iter->is_emoji = FALSE;

  return found_emoji;
}

gboolean pango_emoji_iter_next (PangoEmojiIter *iter)
{
  if (iter->index >= iter->str->len)
    return FALSE;

  guint i = iter->index;
  gboolean found = FALSE;
  PangoEmojiType type = PANGO_EMOJI_NOT_EMOJI;

  while (i < iter->str->len)
    {
      gunichar ch = g_utf8_get_char (iter->str->str + i);
      int ch_len = g_utf8_next_char (iter->str->str + i) - (iter->str->str + i);

      if (g_unichar_is_emoji (ch))
        {
          type = PANGO_EMOJI_EMOJI;
          found = TRUE;
          break;
        }

      if (ch == 0x200D && type == PANGO_EMOJI_EMOJI)
        {
          type = PANGO_EMOJI_EMOJI_EMOJI_SEQUENCE;
          i += ch_len;
          continue;
        }

      if (ch == 0xFE0F && type == PANGO_EMOJI_EMOJI)
        {
          type = PANGO_EMOJI_EMOJI_PRESENTATION_VARIANT;
          i += ch_len;
          continue;
        }

      if (ch == 0xFE0E && type == PANGO_EMOJI_EMOJI)
        {
          type = PANGO_EMOJI_EMOJI_KEYCAP_SEQUENCE;
          i += ch_len;
          continue;
        }

      if (type != PANGO_EMOJI_NOT_EMOJI)
        {
          i += ch_len;
        }
      else
        {
          i += ch_len;
          iter->index = i;
        }
    }

  if (found)
    {
      iter->type = type;
      iter->index = i;
      return TRUE;
    }

  return FALSE;
}

gboolean pango_emoji_iter_next (PangoEmojiIter *iter)
{
  if (iter->index >= iter->str_len)
    return FALSE;

  iter->emoji = FALSE;
  iter->is_base = FALSE;
  iter->is_emoji = FALSE;
  iter->is_emoji_modifier = FALSE;

  gunichar c = g_utf8_get_char (iter->str + iter->index);
  int surrogates = 0;

  if (g_unichar_is_surrogate (c))
    {
      gunichar next_c = g_utf8_get_char (g_utf8_next_char (iter->str + iter->index));
      if (next_c != G_UNICODE_INVALID_CODE_POINT && g_unichar_is_surrogate (next_c))
        {
          surrogates = 2;
          c = 0xFFFFFFFF;
        }
    }

  if (c != G_UNICODE_INVALID_CODE_POINT && !g_unichar_is_surrogate (c))
    {
      if (pango_is_emoji (c))
        {
          iter->emoji = TRUE;
          iter->is_base = TRUE;
          iter->is_emoji = TRUE;
          iter->emoji_type = PANGO_EMOJI_TYPE_EMOJI;
        }
      else if (pango_is_emoji_modifier (c))
        {
          iter->emoji = TRUE;
          iter->is_emoji = TRUE;
          iter->is_emoji_modifier = TRUE;
          iter->emoji_type = PANGO_EMOJI_TYPE_EMOJI_MODIFIER;
        }
    }

  while (iter->index < iter->str_len)
    {
      gunichar c = g_utf8_get_char (iter->str + iter->index);
      if (c == G_UNICODE_INVALID_CODE_POINT)
        break;

      if (iter->emoji)
        {
          if (c == 0xFE0F || c == 0xFE0E)
            {
              iter->emoji_type = PANGO_EMOJI_TYPE_EMOJI_EMOJI_PRESENTATION;
              iter->is_variation_selector = TRUE;
            }
          else if (c == 0x200D)
            {
              iter->emoji_type = PANGO_EMOJI_TYPE_EMOJI_SEQUENCE;
              iter->is_base = FALSE;
            }
          else if (pango_is_emoji_modifier (c))
            {
              iter->emoji_type = PANGO_EMOJI_TYPE_EMOJI_MODIFIER_SEQUENCE;
              iter->is_emoji_modifier = TRUE;
            }
          else
            {
              break;
            }
        }

      g_utf8_next_char (iter->str + iter->index);
      iter->index++;
    }

  if (iter->emoji)
    {
      return TRUE;
    }
  else
    {
      return FALSE;
    }
}
